function wpbp_queries_013( array $post_ids ): WP_Query {
    $post_ids = array_map( 'intval', $post_ids );
    return new WP_Query(
        array(
            'post_type'      => 'post',
            'post_status'    => 'publish',
            'post__in'       => $post_ids,
            'orderby'        => 'post__in',
            'posts_per_page' => count( $post_ids ),
        )
    );
}

function wpbp_queries_014( string $meta_key ): WP_Query {
    return new WP_Query(
        array(
            'post_type'      => 'post',
            'post_status'    => 'publish',
            'meta_key'       => $meta_key,
            'orderby'        => 'meta_value_num',
            'order'          => 'DESC',
            'posts_per_page' => 10,
        )
    );
}

add_action(
    'pre_get_posts',
    static function ( WP_Query $query ) {
        if ( ! $query->is_main_query() ) {
            return;
        }
        $term = get_term_by( 'slug', 'wpbp-q-hidden', 'category' );
        if ( ! $term instanceof WP_Term ) {
            return;
        }
        $excluded = (array) $query->get( 'category__not_in' );
        $excluded[] = (int) $term->term_id;
        $query->set( 'category__not_in', array_values( array_unique( array_filter( $excluded ) ) ) );
    }
);

function wpbp_queries_016( int $page ): WP_Query {
    return new WP_Query(
        array(
            'post_type'      => 'wpbp_q_note',
            'post_status'    => 'publish',
            'posts_per_page' => 3,
            'paged'          => max( 1, $page ),
            'orderby'        => 'date',
            'order'          => 'DESC',
        )
    );
}

function wpbp_queries_017( int $min_price, int $max_price, string $after, string $before ): WP_Query {
    return new WP_Query(
        array(
            'post_type'      => 'post',
            'post_status'    => 'publish',
            'posts_per_page' => 20,
            'meta_query'     => array(
                array(
                    'key'     => 'wpbp_q_price',
                    'value'   => array( $min_price, $max_price ),
                    'compare' => 'BETWEEN',
                    'type'    => 'NUMERIC',
                ),
            ),
            'date_query'     => array(
                array(
                    'after'     => $after,
                    'before'    => $before,
                    'inclusive' => true,
                ),
            ),
        )
    );
}

function wpbp_queries_018( array $author_ids, bool $password_protected ): WP_Query {
    return new WP_Query(
        array(
            'post_type'      => 'post',
            'post_status'    => 'publish',
            'author__in'     => array_map( 'intval', $author_ids ),
            'has_password'   => $password_protected,
            'posts_per_page' => 20,
        )
    );
}

function wpbp_queries_019( string $post_type, string $post_status ): int {
    $counts = wp_count_posts( $post_type );
    if ( ! is_object( $counts ) || ! isset( $counts->{$post_status} ) ) {
        return 0;
    }
    return (int) $counts->{$post_status};
}
